function total($conn,$table){$allowed=['doctor','clinic','manager','book','doctor_availability'];if(!in_array($table,$allowed,true))return 0;$r=$conn->query("SELECT COUNT(*) AS n FROM `$table`");return $r?(int)$r->fetch_assoc()['n']:0;}
